"""Kafka client generated by Mobilis. Application code owns idempotency and state."""

import json
import os
import threading

from kafka import KafkaConsumer, KafkaProducer, OffsetAndMetadata, TopicPartition
from opentelemetry import propagate, trace
from opentelemetry.trace import Link


BOOTSTRAP = [server.strip() for server in os.environ["KAFKA_BOOTSTRAP_SERVERS"].split(",")]
PUBLISH_TOPICS = frozenset(filter(None, os.getenv("MOBILIS_KAFKA_PUBLISH_TOPICS", "").split(",")))
SUBSCRIPTIONS = frozenset(filter(None, os.getenv("MOBILIS_KAFKA_SUBSCRIPTIONS", "").split(",")))
tracer = trace.get_tracer(__name__)


def publish(topic, key, event, headers=None, timeout=10):
    if topic not in PUBLISH_TOPICS:
        raise ValueError(f"Undeclared Kafka publish topic: {topic}")
    if not key:
        raise ValueError("Kafka message key is required")
    producer = KafkaProducer(bootstrap_servers=BOOTSTRAP, acks="all", enable_idempotence=True,
                             request_timeout_ms=int(timeout * 1000))
    carrier = dict(headers or {})
    try:
        with tracer.start_as_current_span("kafka publish", kind=trace.SpanKind.PRODUCER):
            propagate.inject(carrier)
            metadata = producer.send(
                topic, key=str(key).encode(),
                value=json.dumps(event, sort_keys=True, separators=(",", ":")).encode(),
                headers=[(name, str(value).encode()) for name, value in carrier.items()],
            ).get(timeout=timeout)
            return {"topic": metadata.topic, "partition": metadata.partition, "offset": metadata.offset}
    finally:
        producer.close(timeout=timeout)


def consume(topic, group, handler, stop=None):
    """Commit the next offset only after the handler returns successfully.

    A database transaction must persist processed event IDs with its state changes.
    A crash after DB commit and before this offset commit causes safe redelivery.
    """
    if f"{topic}:{group}" not in SUBSCRIPTIONS:
        raise ValueError(f"Undeclared Kafka subscription: {topic}:{group}")
    stop = stop or threading.Event()
    consumer = KafkaConsumer(topic, bootstrap_servers=BOOTSTRAP, group_id=group,
                             enable_auto_commit=False, auto_offset_reset="earliest")
    try:
        while not stop.is_set():
            batches = consumer.poll(timeout_ms=500, max_records=1)
            for messages in batches.values():
                for message in messages:
                    headers = {name: value.decode() for name, value in message.headers if value is not None}
                    parent_context = propagate.extract(headers)
                    parent_span = trace.get_current_span(parent_context).get_span_context()
                    links = [Link(parent_span)] if parent_span.is_valid else []
                    with tracer.start_as_current_span("kafka process", kind=trace.SpanKind.CONSUMER, links=links):
                        handler(json.loads(message.value), message)
                    partition = TopicPartition(message.topic, message.partition)
                    consumer.commit({partition: OffsetAndMetadata(message.offset + 1, "", -1)})
    finally:
        consumer.close()
